/**
 * Startup reindex witnesses for native map growth.
 *
 * <p>
 * Reindexing is run in a child JVM because the pre-fix implementation can continue using a cursor after its writer
 * transaction has been committed and the environment resized. The retained probe output distinguishes seed progress,
 * startup failure, and successful index verification.
 * </p>
 */
public final class ReindexMapFullTest {

	private static final long MAP_SIZE = 2L * 1024 * 1024;
	private static final int SEED_BATCH_SIZE = 64;
	private static final int MAX_SEED_BATCHES = 400;
	private static final int MIN_SEED_ROWS = 1_000;
	private static final int TERM_SEED_BATCH_SIZE = 64;
	private static final int MAX_TERM_SEED_BATCHES = 400;
	private static final int MIN_TERM_ROWS = 1_000;
	private static final String INITIAL_INDEXES = "spoc,posc";
	private static final String REINDEXED_INDEXES = "spoc,posc,ospc,cspo,cpos,cosp";
	private static final String INITIAL_TERM_INDEXES = "spoc,cspo";
	private static final String REINDEXED_TERM_INDEXES = "spoc,cspo,ospc";

	@Test
	public void additionalTripleIndexesRecoverDuringStartupMapGrowth(@TempDir File dataDir) throws Exception {
		String output = runProbe(dataDir, "triple");
		assertTrue(output.contains("PROBE_REINDEX_SEED_MAP_FULL="),
				"the reindex probe did not fill the seed map before startup reindex:\n" + output);
		assertTrue(output.contains("PROBE_REINDEX_SEED_COMMITTED="),
				"the reindex probe did not seed a committed source store:\n" + output);
		assertTrue(output.contains("PROBE_REINDEX_MAP_SIZE_BEFORE="),
				"the reindex probe did not report its source map size:\n" + output);
		assertTrue(output.contains("PROBE_REINDEX_MAP_SIZE_AFTER="),
				"the reindex probe did not report its resized map size:\n" + output);
		assertTrue(output.contains("PROBE_REINDEX_OK"), "the startup reindex probe did not complete:\n" + output);
	}

	@Test
	public void additionalTripleTermIndexesRecoverDuringStartupMapGrowth(@TempDir File dataDir) throws Exception {
		String output = runProbe(dataDir, "term");
		assertTrue(output.contains("PROBE_REINDEX_TERM_SEED_COMMITTED="),
				"the triple-term reindex probe did not seed a committed source store:\n" + output);
		assertTrue(output.contains("PROBE_REINDEX_TERM_MAP_SIZE_BEFORE="),
				"the triple-term reindex probe did not report its source map size:\n" + output);
		assertTrue(output.contains("PROBE_REINDEX_TERM_MAP_SIZE_AFTER="),
				"the triple-term reindex probe did not report its resized map size:\n" + output);
		assertTrue(output.contains("PROBE_REINDEX_TERM_OK"),
				"the triple-term startup reindex probe did not complete:\n" + output);
	}

	private static String runProbe(File dataDir, String mode) throws Exception {
		Path outputFile = Path.of("target", "review-repair-probes",
				"reindex-map-full-" + mode + "-" + System.nanoTime() + ".log");
		Files.createDirectories(outputFile.getParent());
		File childDataDir = new File(dataDir, mode);
		String javaBinary = new File(System.getProperty("java.home"), "bin/java").getAbsolutePath();
		Process process = new ProcessBuilder(javaBinary, "-cp", System.getProperty("java.class.path"),
				ReindexMapFullTest.class.getName(), mode, childDataDir.getAbsolutePath())
						.redirectErrorStream(true)
						.redirectOutput(outputFile.toFile())
						.start();
		try {
			boolean finished = process.waitFor(90, TimeUnit.SECONDS);
			if (!finished) {
				String threadDump = captureThreadDump(process, outputFile);
				process.destroyForcibly();
				boolean exited = process.waitFor(5, TimeUnit.SECONDS);
				String output = readProbeOutput(outputFile);
				if (!exited || process.isAlive()) {
					fail("reindex " + mode + " probe could not be forcibly terminated (output file=" + outputFile
							+ ", thread dump=" + threadDump + "):\n" + output);
				}
				fail("reindex " + mode + " probe timed out (output file=" + outputFile + ", thread dump="
						+ threadDump + "):\n" + output);
			}
			String output = readProbeOutput(outputFile);
			assertEquals(0, process.exitValue(),
					"reindex " + mode + " probe output file " + outputFile + ":\n" + output);
			return output;
		} finally {
			if (process.isAlive()) {
				process.destroyForcibly();
				if (!process.waitFor(5, TimeUnit.SECONDS) || process.isAlive()) {
					fail("reindex " + mode + " probe remained alive during cleanup (output file=" + outputFile + ")");
				}
			}
		}
	}

	private static String captureThreadDump(Process process, Path outputFile) {
		Path threadDumpFile = outputFile.resolveSibling(outputFile.getFileName() + ".threads");
		File jcmd = new File(System.getProperty("java.home"), "bin/jcmd");
		Process dump = null;
		try {
			dump = new ProcessBuilder(jcmd.getAbsolutePath(), Long.toString(process.pid()), "Thread.print")
					.redirectErrorStream(true)
					.redirectOutput(threadDumpFile.toFile())
					.start();
			boolean finished = dump.waitFor(5, TimeUnit.SECONDS);
			if (!finished) {
				dump.destroyForcibly();
				if (!dump.waitFor(5, TimeUnit.SECONDS)) {
					return "unavailable (jcmd did not exit; file=" + threadDumpFile + ")";
				}
			}
			return threadDumpFile + ":\n" + readProbeOutput(threadDumpFile);
		} catch (IOException e) {
			return "unavailable (" + e + ")";
		} catch (InterruptedException e) {
			Thread.currentThread().interrupt();
			return "unavailable (interrupted while running jcmd)";
		} finally {
			if (dump != null && dump.isAlive()) {
				dump.destroyForcibly();
			}
		}
	}

	private static String readProbeOutput(Path outputFile) throws IOException {
		return Files.exists(outputFile) ? Files.readString(outputFile, StandardCharsets.UTF_8) : "";
	}

	public static void main(String[] args) throws Exception {
		if (args.length != 2) {
			throw new IllegalArgumentException("expected probe mode and data directory");
		}
		try {
			switch (args[0]) {
			case "triple":
				runTripleStoreProbe(new File(args[1]));
				break;
			case "term":
				runValueStoreProbe(new File(args[1]));
				break;
			default:
				throw new IllegalArgumentException("unknown probe mode: " + args[0]);
			}
		} catch (Exception | Error e) {
			System.out.println("PROBE_REINDEX_FAILURE=" + e.getClass().getName() + ":" + e.getMessage());
			throw e;
		}
	}

	private static void runTripleStoreProbe(File dataDir) throws Exception {
		LmdbStoreConfig seedConfig = new LmdbStoreConfig(INITIAL_INDEXES)
				.setTripleDBSize(MAP_SIZE)
				.setAutoGrow(false);
		StoreProperties properties = new StoreProperties(dataDir);
		int explicitRows;
		int inferredRows;
		long mapSizeBefore;
		try (TripleStore store = new TripleStore(dataDir, properties, seedConfig, null)) {
			int[] counts = seedTripleStore(store);
			explicitRows = counts[0];
			inferredRows = counts[1];
			try (Txn txn = store.getTxnManager().createReadTxn()) {
				mapSizeBefore = mapSizeOf(txn.get());
			}
		}
		properties.save();
		System.out.println("PROBE_REINDEX_MAP_SIZE_BEFORE=" + mapSizeBefore);

		StoreProperties reopenedProperties = new StoreProperties(dataDir);
		require(reopenedProperties.load(), "the initial store properties were not persisted");
		LmdbStoreConfig reindexConfig = new LmdbStoreConfig(REINDEXED_INDEXES)
				.setTripleDBSize(MAP_SIZE)
				.setAutoGrow(true);
		System.out.println("PROBE_REINDEX_BEFORE_OPEN");
		try (TripleStore store = new TripleStore(dataDir, reopenedProperties, reindexConfig, null)) {
			System.out.println("PROBE_REINDEX_OPENED");
			long mapSizeAfter;
			try (Txn txn = store.getTxnManager().createReadTxn()) {
				mapSizeAfter = mapSizeOf(txn.get());
				require(count(store.getTriples(txn, -1, -1, -1, -1, true)) == explicitRows,
						"explicit rows changed during startup reindex");
				require(count(store.getTriples(txn, -1, -1, -1, -1, false)) == inferredRows,
						"inferred rows changed during startup reindex");
				assertIndexEntries(store.getLmdbStats(), REINDEXED_INDEXES, explicitRows, inferredRows);
				assertRepresentativeLookups(store, txn, true);
				assertRepresentativeLookups(store, txn, false);
			}
			System.out.println("PROBE_REINDEX_MAP_SIZE_AFTER=" + mapSizeAfter);
			require(mapSizeAfter > mapSizeBefore, "startup reindex must grow the native map");
		}
		reopenedProperties.save();
		StoreProperties persistedProperties = new StoreProperties(dataDir);
		require(persistedProperties.load(), "the reindexed triple-store properties were not persisted");
		require(REINDEXED_INDEXES.equals(persistedProperties.getTripleIndexes()),
				"the reindexed triple indexes were not persisted");
		try (TripleStore store = new TripleStore(dataDir, persistedProperties, reindexConfig, null);
				Txn txn = store.getTxnManager().createReadTxn()) {
			assertIndexEntries(store.getLmdbStats(), REINDEXED_INDEXES, explicitRows, inferredRows);
			assertRepresentativeLookups(store, txn, true);
			assertRepresentativeLookups(store, txn, false);
		}
		System.out.println("PROBE_REINDEX_PERSISTED");
		System.out.println("PROBE_REINDEX_OK");
	}

	private static void runValueStoreProbe(File dataDir) throws Exception {
		LmdbStoreConfig seedConfig = new LmdbStoreConfig()
				.setValueDBSize(MAP_SIZE)
				.setAutoGrow(false)
				.setTripleTermIndexes(INITIAL_TERM_INDEXES);
		StoreProperties properties = new StoreProperties(dataDir);
		ValueStoreSeed seed;
		long mapSizeBefore;
		ValueStore store = new ValueStore(dataDir, properties, seedConfig);
		try {
			seed = seedValueStore(store);
			try (Txn txn = store.getTxnManager().createReadTxn()) {
				mapSizeBefore = mapSizeOf(txn.get());
			}
			System.out.println("PROBE_REINDEX_TERM_SEED_COMMITTED=" + seed.termCount());
		} finally {
			store.close();
		}
		properties.save();
		System.out.println("PROBE_REINDEX_TERM_MAP_SIZE_BEFORE=" + mapSizeBefore);

		StoreProperties reopenedProperties = new StoreProperties(dataDir);
		require(reopenedProperties.load(), "the initial value-store properties were not persisted");
		LmdbStoreConfig reindexConfig = new LmdbStoreConfig()
				.setValueDBSize(MAP_SIZE)
				.setAutoGrow(true)
				.setTripleTermIndexes(REINDEXED_TERM_INDEXES);
		System.out.println("PROBE_REINDEX_TERM_BEFORE_OPEN");
		store = new ValueStore(dataDir, reopenedProperties, reindexConfig);
		try {
			System.out.println("PROBE_REINDEX_TERM_OPENED");
			long mapSizeAfter;
			try (Txn txn = store.getTxnManager().createReadTxn()) {
				mapSizeAfter = mapSizeOf(txn.get());
			}
			int indexedTerms = count(store.getTripleTerms(-1, -1, -1));
			require(indexedTerms == seed.termCount(), "triple-term rows changed during startup reindex");
			LmdbStore.LmdbDatabaseStats addedIndex = store.getLmdbStats().get(valueDatabaseName("ospc"));
			require(addedIndex != null && addedIndex.entries() == seed.termCount(),
					"the added triple-term index does not contain every source row");
			assertStableTerm(store, seed.firstTerm(), seed.firstId());
			assertStableTerm(store, seed.lastTerm(), seed.lastId());
			System.out.println("PROBE_REINDEX_TERM_MAP_SIZE_AFTER=" + mapSizeAfter);
			require(mapSizeAfter > mapSizeBefore, "triple-term startup reindex must grow the native map");
		} finally {
			store.close();
		}
		reopenedProperties.save();
		StoreProperties persistedProperties = new StoreProperties(dataDir);
		require(persistedProperties.load(), "the reindexed value-store properties were not persisted");
		require(REINDEXED_TERM_INDEXES.equals(persistedProperties.getTripleTermIndexes()),
				"the reindexed triple-term indexes were not persisted");
		store = new ValueStore(dataDir, persistedProperties, reindexConfig);
		try {
			require(count(store.getTripleTerms(-1, -1, -1)) == seed.termCount(),
					"triple-term rows changed after reopening the reindexed store");
			LmdbStore.LmdbDatabaseStats addedIndex = store.getLmdbStats().get(valueDatabaseName("ospc"));
			require(addedIndex != null && addedIndex.entries() == seed.termCount(),
					"the added triple-term index was not persisted");
			assertStableTerm(store, seed.firstTerm(), seed.firstId());
			assertStableTerm(store, seed.lastTerm(), seed.lastId());
		} finally {
			store.close();
		}
		System.out.println("PROBE_REINDEX_TERM_PERSISTED");
		System.out.println("PROBE_REINDEX_TERM_OK");
	}

	private static ValueStoreSeed seedValueStore(ValueStore store) throws IOException {
		IRI subject = Values.iri("urn:reindex-term-subject");
		IRI predicate = Values.iri("urn:reindex-term-predicate");
		int termCount = 0;
		TripleTerm firstTerm = null;
		TripleTerm lastTerm = null;
		long firstId = LmdbValue.UNKNOWN_ID;
		long lastId = LmdbValue.UNKNOWN_ID;
		for (int batch = 0; batch < MAX_TERM_SEED_BATCHES; batch++) {
			store.startTransaction(true);
			int batchTerms = 0;
			TripleTerm batchFirstTerm = null;
			TripleTerm batchLastTerm = null;
			long batchFirstId = LmdbValue.UNKNOWN_ID;
			long batchLastId = LmdbValue.UNKNOWN_ID;
			try {
				for (int i = 0; i < TERM_SEED_BATCH_SIZE; i++) {
					long row = (long) batch * TERM_SEED_BATCH_SIZE + i;
					TripleTerm term = Values.tripleTerm(subject, predicate,
							Values.iri("urn:reindex-term-object-" + row));
					long id = store.storeValue(term);
					require(id > 0, "triple-term seed ID was invalid");
					if (batchFirstTerm == null) {
						batchFirstTerm = term;
						batchFirstId = id;
					}
					batchLastTerm = term;
					batchLastId = id;
					batchTerms++;
				}
				store.commit();
				if (firstTerm == null) {
					firstTerm = batchFirstTerm;
					firstId = batchFirstId;
				}
				lastTerm = batchLastTerm;
				lastId = batchLastId;
				termCount += batchTerms;
			} catch (IOException | RuntimeException | Error e) {
				try {
					store.rollback();
				} catch (Throwable cleanupFailure) {
					e.addSuppressed(cleanupFailure);
				}
				if (e instanceof IOException && mdb_strerror(MDB_MAP_FULL).equals(e.getMessage())) {
					System.out.println("PROBE_REINDEX_TERM_SEED_MAP_FULL=" + e.getMessage());
					break;
				}
				throw e;
			}
		}
		require(termCount >= MIN_TERM_ROWS, "insufficient committed triple-term rows for reindex growth");
		return new ValueStoreSeed(termCount, firstTerm, firstId, lastTerm, lastId);
	}

	private static int[] seedTripleStore(TripleStore store) throws IOException {
		int explicitRows = 0;
		int inferredRows = 0;
		boolean mapFullObserved = false;
		for (int batch = 0; batch < MAX_SEED_BATCHES; batch++) {
			store.startTransaction();
			int batchExplicitRows = 0;
			int batchInferredRows = 0;
			try {
				for (int i = 0; i < SEED_BATCH_SIZE; i++) {
					long row = (long) batch * SEED_BATCH_SIZE + i;
					require(store.storeTriple(1_000_000L + row, 10L + row % 17, 2_000_000L + row,
							100L + row % 11, true), "explicit seed row was unexpectedly a duplicate");
					batchExplicitRows++;
					require(store.storeTriple(3_000_000L + row, 30L + row % 17, 4_000_000L + row,
							200L + row % 11, false), "inferred seed row was unexpectedly a duplicate");
					batchInferredRows++;
				}
				store.commit();
				explicitRows += batchExplicitRows;
				inferredRows += batchInferredRows;
			} catch (IOException | RuntimeException | Error e) {
				try {
					store.rollback();
				} catch (Throwable cleanupFailure) {
					e.addSuppressed(cleanupFailure);
				}
				if (e instanceof IOException && mdb_strerror(MDB_MAP_FULL).equals(e.getMessage())) {
					System.out.println("PROBE_REINDEX_SEED_MAP_FULL=" + e.getMessage());
					mapFullObserved = true;
					break;
				}
				throw e;
			}
		}
		System.out.println("PROBE_REINDEX_SEED_COMMITTED=" + (explicitRows + inferredRows));
		require(mapFullObserved, "seed did not reach native MAP_FULL before the batch limit");
		require(explicitRows + inferredRows >= MIN_SEED_ROWS, "insufficient committed source rows for reindex growth");
		return new int[] { explicitRows, inferredRows };
	}

	private static void assertIndexEntries(Map<String, LmdbStore.LmdbDatabaseStats> stats, String indexSpecs,
			int explicitRows, int inferredRows) {
		for (String fieldSeq : indexSpecs.split(",")) {
			LmdbStore.LmdbDatabaseStats explicit = stats.get(tripleDatabaseName(fieldSeq, true));
			LmdbStore.LmdbDatabaseStats inferred = stats.get(tripleDatabaseName(fieldSeq, false));
			require(explicit != null && explicit.entries() == explicitRows,
					"explicit " + fieldSeq + " index does not contain every source row");
			require(inferred != null && inferred.entries() == inferredRows,
					"inferred " + fieldSeq + " index does not contain every source row");
		}
	}

	private static String tripleDatabaseName(String fieldSeq, boolean explicit) {
		String name = fieldSeq;
		return name + (explicit ? name : name + "-inf");
	}

	private static void assertRepresentativeLookups(TripleStore store, Txn txn, boolean explicit) throws IOException {
		long subject = explicit ? 1_000_000L : 3_000_000L;
		long predicate = explicit ? 10L : 30L;
		long object = explicit ? 2_000_000L : 4_000_000L;
		long context = explicit ? 100L : 200L;
		assertSelectedLookup(store, txn, "ospc", -1, -1, object, -1, explicit);
		assertSelectedLookup(store, txn, "cspo", subject, predicate, -1, context, explicit);
		assertSelectedLookup(store, txn, "cpos", -1, predicate, object, context, explicit);
		assertSelectedLookup(store, txn, "cosp", subject, -1, object, context, explicit);
	}

	private static void assertSelectedLookup(TripleStore store, Txn txn, String expectedIndex, long subject,
			long predicate, long object, long context, boolean explicit) throws IOException {
		try (RecordIterator records = store.getTriples(txn, subject, predicate, object, context, explicit)) {
			require(expectedIndex.equals(records.getIndexName()),
					"the selective lookup used " + records.getIndexName() + " instead of " + expectedIndex);
			require(records.next() != null, "the " + expectedIndex + " selective lookup returned no row");
			require(records.next() == null, "the " + expectedIndex + " selective lookup returned duplicate rows");
		}
	}

	private static String valueDatabaseName(String fieldSeq) {
		String name = "term-" + fieldSeq;
		return name + name;
	}

	private static void assertStableTerm(ValueStore store, TripleTerm expectedTerm, long expectedId)
			throws IOException {
		require(store.getId(expectedTerm) == expectedId, "triple-term ID changed during index reindex");
		var actual = store.getValue(expectedId);
		require(actual != null && expectedTerm.equals(actual), "triple-term value changed during index reindex");
	}

	private record ValueStoreSeed(int termCount, TripleTerm firstTerm, long firstId, TripleTerm lastTerm, long lastId) {
	}

	private static int count(RecordIterator iterator) {
		int count = 0;
		try (iterator) {
			while (iterator.next() != null) {
				count++;
			}
		}
		return count;
	}

	private static long mapSizeOf(long txn) throws IOException {
		try (MemoryStack stack = MemoryStack.stackPush()) {
			MDBEnvInfo info = MDBEnvInfo.malloc(stack);
			int result = mdb_env_info(mdb_txn_env(txn), info);
			if (result != MDB_SUCCESS) {
				throw new IOException(mdb_strerror(result));
			}
			return info.me_mapsize();
		}
	}

	private static void require(boolean condition, String message) {
		if (!condition) {
			throw new AssertionError(message);
		}
	}
}
